SELECT CAST(COUNT(DISTINCT CASE WHEN p.gender = 'M' AND EXTRACT(YEAR FROM AGE(p.anchor_year)) BETWEEN 39 AND 49 AND d.icd_code = '4260' THEN a.hadm_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.hadm_id), 0) AS proportion, COUNT(DISTINCT CASE WHEN p.gender = 'M' AND EXTRACT(YEAR FROM AGE(p.anchor_year)) BETWEEN 39 AND 49 AND d.icd_code = '4260' THEN a.hadm_id END) AS count, COUNT(DISTINCT CASE WHEN p.gender = 'M' AND EXTRACT(YEAR FROM AGE(p.anchor_year)) BETWEEN 39 AND 49 AND d.icd_code = '4260' THEN a.hadm_id END) / NULLIF(COUNT(DISTINCT a.hadm_id), 0) * 100 AS percentage, AVG(l.value) AS average_value, MEDIAN(l.value) AS median_value, (percentile_cont(0.75) within GROUP (ORDER BY l.value) - percentile_cont(0.25) within GROUP (ORDER BY l.value)) AS interquartile_range FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id JOIN labevents l ON a.hadm_id = l.hadm_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM AGE(p.anchor_year)) BETWEEN 39 AND 49 AND d.icd_code = '4260' GROUP BY a.hadm_id;